#
Set-StrictMode -Version Latest
$ErrorActionPreference = "Continue"
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName PresentationFramework
Add-Type -AssemblyName PresentationCore
Add-Type -AssemblyName WindowsBase
[System.Windows.Forms.Application]::EnableVisualStyles()
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12

# ============================================
# ADMIN ELEVATION CHECK
# ============================================
# SETTDash requires Administrator privileges (registry/service/system operations rely on it).
$Script:IsElevated = $false
try {
    $currentPrincipal = New-Object System.Security.Principal.WindowsPrincipal([System.Security.Principal.WindowsIdentity]::GetCurrent())
    $Script:IsElevated = $currentPrincipal.IsInRole([System.Security.Principal.WindowsBuiltInRole]::Administrator)
} catch { $Script:IsElevated = $false }

if (-not $Script:IsElevated) {
    [System.Windows.Forms.MessageBox]::Show(
        "SETTDash precisa ser executado como Administrador.`nMuitas funcoes (registro, servicos, cache) falharao silenciosamente sem elevacao.`n`nPor favor feche e execute novamente como Administrador.",
        "SETTDash - Privilegios insuficientes",
        [System.Windows.Forms.MessageBoxButtons]::OK,
        [System.Windows.Forms.MessageBoxIcon]::Warning
    ) | Out-Null
    exit 1
}

# ============================================
# SETTDash v3.2
# ============================================
$Script:AppDir = try {
    [System.IO.Path]::GetDirectoryName([System.Diagnostics.Process]::GetCurrentProcess().MainModule.FileName)
} catch { }
if ([string]::IsNullOrEmpty($Script:AppDir)) { $Script:AppDir = if ($PSScriptRoot) { $PSScriptRoot } }
if ([string]::IsNullOrEmpty($Script:AppDir)) { $Script:AppDir = if ($MyInvocation.MyCommand.Path) { Split-Path -Parent $MyInvocation.MyCommand.Path } }
if ([string]::IsNullOrEmpty($Script:AppDir)) { $Script:AppDir = Split-Path -Parent $PSCommandPath }
if ([string]::IsNullOrEmpty($Script:AppDir)) { $Script:AppDir = Get-Location | Select-Object -ExpandProperty Path }
$Script:TempDir = Join-Path $env:TEMP "SETTDash"
if (-not (Test-Path $Script:TempDir)) { New-Item -Path $Script:TempDir -ItemType Directory -Force | Out-Null }
#region XAML DASHBOARD LAYOUT
[xml]$xaml = @"
<Window
    xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
    xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
    Width="1500" Height="800"
    WindowStyle="None"
    AllowsTransparency="True"
    Background="#0D1117"
    BorderBrush="#30363D"
    BorderThickness="1"
    ResizeMode="CanResizeWithGrip">

    <Window.Resources>
        <!-- ==================== NAV BUTTON STYLE ==================== -->
        <Style x:Key="NavButtonStyle" TargetType="Button">
            <Setter Property="Background" Value="Transparent"/>
            <Setter Property="Foreground" Value="#C9D1D9"/>
            <Setter Property="FontSize" Value="13"/>
            <Setter Property="Height" Value="38"/>
            <Setter Property="HorizontalContentAlignment" Value="Left"/>
            <Setter Property="Padding" Value="16,0,0,0"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="BorderThickness" Value="0"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="border" Background="{TemplateBinding Background}"
                                Padding="{TemplateBinding Padding}"
                                CornerRadius="0">
                            <ContentPresenter HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}"
                                              VerticalAlignment="Center"
                                              TextBlock.Foreground="{TemplateBinding Foreground}"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="border" Property="Background" Value="#21262D"/>
                            </Trigger>
                            <Trigger Property="IsPressed" Value="True">
                                <Setter TargetName="border" Property="Background" Value="#30363D"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- ==================== NAV BUTTON ACTIVE STYLE ==================== -->
        <!-- Reuses NavButtonStyle's template; only overrides the colors that differ when a nav item is active. -->
        <Style x:Key="NavButtonActiveStyle" TargetType="Button" BasedOn="{StaticResource NavButtonStyle}">
            <Setter Property="Background" Value="#1F6FEB"/>
            <Setter Property="Foreground" Value="White"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
        </Style>

        <!-- ==================== NAV HEADER STYLE ==================== -->
        <Style x:Key="NavHeaderStyle" TargetType="Button">
            <Setter Property="Foreground" Value="#8B949E"/>
            <Setter Property="FontSize" Value="11"/>
            <Setter Property="FontWeight" Value="Bold"/>
            <Setter Property="Height" Value="28"/>
            <Setter Property="Margin" Value="16,10,0,4"/>
            <Setter Property="Background" Value="Transparent"/>
            <Setter Property="BorderThickness" Value="0"/>
            <Setter Property="HorizontalContentAlignment" Value="Left"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border Background="{TemplateBinding Background}" Padding="0,0,0,0">
                            <ContentPresenter HorizontalAlignment="Left" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter Property="Foreground" Value="#C9D1D9"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- ==================== ACTION BUTTON STYLE ==================== -->
        <Style x:Key="ActionButtonStyle" TargetType="Button">
            <Setter Property="Background" Value="#238636"/>
            <Setter Property="Foreground" Value="White"/>
            <Setter Property="FontSize" Value="13"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
            <Setter Property="MinHeight" Value="52"/>
            <Setter Property="MinWidth" Value="150"/>
            <Setter Property="Width" Value="Auto"/>
            <Setter Property="Padding" Value="16,4"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="BorderThickness" Value="0"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="border" Background="{TemplateBinding Background}"
                                Padding="{TemplateBinding Padding}"
                                CornerRadius="6"
                                MinHeight="{TemplateBinding MinHeight}"
                                MinWidth="{TemplateBinding MinWidth}">
                         <TextBlock Text="{TemplateBinding Content}"
                                       TextWrapping="Wrap"
                                       HorizontalAlignment="Center"
                                       VerticalAlignment="Center"
                                       Foreground="{TemplateBinding Foreground}"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="border" Property="Background" Value="#2EA043"/>
                            </Trigger>
                            <Trigger Property="IsPressed" Value="True">
                                <Setter TargetName="border" Property="Background" Value="#196C2E"/>
                            </Trigger>
                            <Trigger Property="IsEnabled" Value="False">
                                <Setter TargetName="border" Property="Background" Value="#21262D"/>
                                <Setter Property="Foreground" Value="#484F58"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- ==================== REVERT BUTTON STYLE ==================== -->
        <Style x:Key="RevertButtonStyle" TargetType="Button">
            <Setter Property="Background" Value="#21262D"/>
            <Setter Property="Foreground" Value="#C9D1D9"/>
            <Setter Property="FontSize" Value="13"/>
            <Setter Property="MinHeight" Value="42"/>
            <Setter Property="MinWidth" Value="180"/>
            <Setter Property="Width" Value="Auto"/>
            <Setter Property="Padding" Value="16,0"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="BorderThickness" Value="0"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="border" Background="{TemplateBinding Background}"
                                Padding="{TemplateBinding Padding}"
                                CornerRadius="6"
                                MinHeight="{TemplateBinding MinHeight}"
                                MinWidth="{TemplateBinding MinWidth}">
                         <TextBlock Text="{TemplateBinding Content}"
                                       TextWrapping="Wrap"
                                       HorizontalAlignment="Center"
                                       VerticalAlignment="Center"
                                       Foreground="{TemplateBinding Foreground}"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="border" Property="Background" Value="#30363D"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- ==================== DANGER BUTTON STYLE ==================== -->
        <Style x:Key="DangerButtonStyle" TargetType="Button">
            <Setter Property="Background" Value="#DA3633"/>
            <Setter Property="Foreground" Value="White"/>
            <Setter Property="FontSize" Value="13"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
            <Setter Property="MinHeight" Value="42"/>
            <Setter Property="MinWidth" Value="180"/>
            <Setter Property="Width" Value="Auto"/>
            <Setter Property="Padding" Value="16,0"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="BorderThickness" Value="0"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="border" Background="{TemplateBinding Background}"
                                Padding="{TemplateBinding Padding}"
                                CornerRadius="6"
                                MinHeight="{TemplateBinding MinHeight}"
                                MinWidth="{TemplateBinding MinWidth}">
                         <TextBlock Text="{TemplateBinding Content}"
                                       TextWrapping="Wrap"
                                       HorizontalAlignment="Center"
                                       VerticalAlignment="Center"
                                       Foreground="{TemplateBinding Foreground}"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="border" Property="Background" Value="#F85149"/>
                            </Trigger>
                            <Trigger Property="IsEnabled" Value="False">
                                <Setter TargetName="border" Property="Background" Value="#21262D"/>
                                <Setter Property="Foreground" Value="#484F58"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- ==================== TOOL BUTTON STYLE ==================== -->
        <Style x:Key="ToolButtonStyle" TargetType="Button">
            <Setter Property="Background" Value="#1F6FEB"/>
            <Setter Property="Foreground" Value="White"/>
            <Setter Property="FontSize" Value="12"/>
            <Setter Property="MinHeight" Value="36"/>
            <Setter Property="MinWidth" Value="130"/>
            <Setter Property="Padding" Value="12,0"/>
            <Setter Property="BorderThickness" Value="0"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border Background="{TemplateBinding Background}" CornerRadius="6" Padding="{TemplateBinding Padding}">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter Property="Background" Value="#388BFD"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- ==================== CARD STYLE ==================== -->
        <Style x:Key="CardStyle" TargetType="Border">
            <Setter Property="Background" Value="#161B22"/>
            <Setter Property="BorderBrush" Value="#30363D"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="CornerRadius" Value="8"/>
            <Setter Property="Padding" Value="16"/>
            <Setter Property="Margin" Value="0,0,0,12"/>
        </Style>

        <!-- ==================== CARD TITLE STYLE ==================== -->
        <Style x:Key="CardTitleStyle" TargetType="TextBlock">
            <Setter Property="Foreground" Value="#E6EDF3"/>
            <Setter Property="FontSize" Value="15"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
            <Setter Property="Margin" Value="0,0,0,8"/>
        </Style>

        <!-- ==================== CARD DESCRIPTION STYLE ==================== -->
        <Style x:Key="CardDescStyle" TargetType="TextBlock">
            <Setter Property="Foreground" Value="#8B949E"/>
            <Setter Property="FontSize" Value="12"/>
            <Setter Property="TextWrapping" Value="Wrap"/>
            <Setter Property="Margin" Value="0,0,0,14"/>
        </Style>

        <!-- ==================== PAGE TITLE STYLE ==================== -->
        <Style x:Key="PageTitleStyle" TargetType="TextBlock">
            <Setter Property="Foreground" Value="#E6EDF3"/>
            <Setter Property="FontSize" Value="22"/>
            <Setter Property="FontWeight" Value="Bold"/>
            <Setter Property="Margin" Value="0,10,0,20"/>
        </Style>

        <!-- ==================== PROGRESS BAR STYLE ==================== -->
        <Style x:Key="ProgressBarStyle" TargetType="ProgressBar">
            <Setter Property="Height" Value="10"/>
            <Setter Property="Background" Value="#21262D"/>
            <Setter Property="Foreground" Value="#1F6FEB"/>
            <Setter Property="BorderThickness" Value="0"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="ProgressBar">
                        <Grid>
                            <Border Background="{TemplateBinding Background}"
                                    CornerRadius="3" BorderThickness="0"/>
                            <Border x:Name="PART_Track" Background="Transparent"
                                    CornerRadius="3" BorderThickness="0">
                                <Border x:Name="PART_Indicator" Background="#1F6FEB"
                                        CornerRadius="3" BorderThickness="0"
                                        HorizontalAlignment="Left"/>
                            </Border>
                        </Grid>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- ==================== CLOSE BUTTON STYLE ==================== -->
        <Style x:Key="CloseButtonStyle" TargetType="Button">
            <Setter Property="Background" Value="Transparent"/>
            <Setter Property="Foreground" Value="#8B949E"/>
            <Setter Property="FontSize" Value="16"/>
            <Setter Property="Width" Value="46"/>
            <Setter Property="Height" Value="32"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="BorderThickness" Value="0"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="border" Background="{TemplateBinding Background}"
                                Width="{TemplateBinding Width}"
                                Height="{TemplateBinding Height}">
                         <TextBlock Text="{TemplateBinding Content}"
                                       TextWrapping="Wrap"
                                       HorizontalAlignment="Center"
                                       VerticalAlignment="Center"
                                       Foreground="{TemplateBinding Foreground}"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="border" Property="Background" Value="#DA3633"/>
                                <Setter Property="Foreground" Value="White"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- ==================== MINIMIZE BUTTON STYLE ==================== -->
        <Style x:Key="MinButtonStyle" TargetType="Button">
            <Setter Property="Background" Value="Transparent"/>
            <Setter Property="Foreground" Value="#8B949E"/>
            <Setter Property="FontSize" Value="16"/>
            <Setter Property="Width" Value="46"/>
            <Setter Property="Height" Value="32"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="BorderThickness" Value="0"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="border" Background="{TemplateBinding Background}"
                                Width="{TemplateBinding Width}"
                                Height="{TemplateBinding Height}">
                         <TextBlock Text="{TemplateBinding Content}"
                                       TextWrapping="Wrap"
                                       HorizontalAlignment="Center"
                                       VerticalAlignment="Center"
                                       Foreground="{TemplateBinding Foreground}"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="border" Property="Background" Value="#30363D"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- ==================== SCROLLBAR STYLE ==================== -->
        <Style x:Key="ScrollBarStyle" TargetType="ScrollBar">
            <Setter Property="Width" Value="8"/>
            <Setter Property="Background" Value="#161B22"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="ScrollBar">
                        <Border Background="{TemplateBinding Background}" CornerRadius="4">
                            <Track x:Name="PART_Track" IsDirectionReversed="True">
                                <Track.Thumb>
                                    <Thumb Background="#30363D" BorderThickness="0" Width="6">
                                        <Thumb.Template>
                                            <ControlTemplate TargetType="Thumb">
                                                <Border Background="{TemplateBinding Background}" CornerRadius="4"/>
                                            </ControlTemplate>
                                        </Thumb.Template>
                                    </Thumb>
                                </Track.Thumb>
                            </Track>
                        </Border>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

    </Window.Resources>

    <!-- ==================== ROOT GRID ==================== -->
    <Grid>
        <Grid.RowDefinitions>
            <RowDefinition Height="32"/>
            <RowDefinition Height="*"/>
        </Grid.RowDefinitions>

        <!-- ==================== TITLE BAR ==================== -->
        <Border Grid.Row="0" x:Name="titleBar" Background="#161B22"
                BorderBrush="#30363D" BorderThickness="0,0,0,1">
            <Grid>
                <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="Auto"/>
                    <ColumnDefinition Width="Auto"/>
                    <ColumnDefinition Width="Auto"/>
                    <ColumnDefinition Width="Auto"/>
                    <ColumnDefinition Width="Auto"/>
                    <ColumnDefinition Width="*"/>
                    <ColumnDefinition Width="Auto"/>
                    <ColumnDefinition Width="Auto"/>
                    <ColumnDefinition Width="Auto"/>
                </Grid.ColumnDefinitions>

                <TextBlock Grid.Column="0" Text="SETT OPTIMIZER Dashboard v3.2"
                           Foreground="#E6EDF3" FontSize="12" FontWeight="SemiBold"
                           VerticalAlignment="Center" Margin="12,0,0,0"/>

                <TextBlock Grid.Column="1" Text="|" Foreground="#30363D"
                           FontSize="12" VerticalAlignment="Center" Margin="8,0"/>

                <TextBlock Grid.Column="2" x:Name="TxtCPU" Text="CPU: --"
                           Foreground="#8B949E" FontSize="11"
                           VerticalAlignment="Center" Margin="0,0,12,0"/>

                <TextBlock Grid.Column="3" x:Name="TxtRAM" Text="RAM: --"
                           Foreground="#8B949E" FontSize="11"
                           VerticalAlignment="Center" Margin="0,0,12,0"/>

                <TextBlock Grid.Column="4" x:Name="TxtOS" Text="OS: --"
                           Foreground="#8B949E" FontSize="11"
                           VerticalAlignment="Center" Margin="0,0,12,0"/>

                <Border Grid.Column="6" Background="Transparent">
                    <Button x:Name="btnMin" Content="_" Style="{StaticResource MinButtonStyle}"/>
                </Border>

                <Border Grid.Column="7" Background="Transparent">
                    <Button x:Name="btnMax" Content="[ ]" Style="{StaticResource MinButtonStyle}"/>
                </Border>

                <Border Grid.Column="8" Background="Transparent">
                    <Button x:Name="btnClose" Content="X" Style="{StaticResource CloseButtonStyle}"/>
                </Border>
            </Grid>
        </Border>

        <!-- ==================== MAIN CONTENT ==================== -->
        <Grid Grid.Row="1">
            <Grid.ColumnDefinitions>
                <ColumnDefinition Width="220"/>
                <ColumnDefinition Width="*"/>
            </Grid.ColumnDefinitions>

            <!-- ==================== LEFT SIDEBAR ==================== -->
            <Border Grid.Column="0" Background="#0D1117"
                    BorderBrush="#30363D" BorderThickness="0,0,1,0">
                <ScrollViewer VerticalScrollBarVisibility="Auto"
                              Style="{x:Null}">
                    <StackPanel x:Name="pnlNav">

                        <!-- QUICK section (always visible) -->
                        <Button x:Name="hdrQuick" Content="QUICK" Style="{StaticResource NavHeaderStyle}" IsEnabled="False"/>
                    <Button x:Name="navHome" Content="★  Home" Style="{StaticResource NavButtonStyle}" Tag="pageHome"/>
                    <Button x:Name="navAll" Content="⚡  Optimize All" Style="{StaticResource NavButtonStyle}" Tag="pageAll"/>

                        <!-- INSTALLERS section (collapsible) -->
                        <Button x:Name="hdrInstallers" Content="[+] INSTALLERS" Style="{StaticResource NavHeaderStyle}"/>
                        <StackPanel x:Name="secInstallers" Visibility="Collapsed">
                            <Button x:Name="navInstallers" Content="⚡  Essentials" Style="{StaticResource NavButtonStyle}" Tag="pageInstallers"/>
                            <Button x:Name="navGpuProgs" Content="⚡  GPU Software" Style="{StaticResource NavButtonStyle}" Tag="pageGpuSoftware"/>
                            <Button x:Name="navCpuProgs" Content="⚡  CPU Software" Style="{StaticResource NavButtonStyle}" Tag="pageCpuSoftware"/>
                            <Button x:Name="navAllInstallers" Content="⚡  ALL Programs" Style="{StaticResource NavButtonStyle}" Tag="pageAllInstallers"/>
                        </StackPanel>

                        <!-- SYSTEM section (collapsible) -->
                        <Button x:Name="hdrSystem" Content="[+] SYSTEM" Style="{StaticResource NavHeaderStyle}"/>
                        <StackPanel x:Name="secSystem" Visibility="Collapsed">
                            <Button x:Name="navInternet" Content="⚡  Internet" Style="{StaticResource NavButtonStyle}" Tag="pageInternet"/>
                            <Button x:Name="navPower" Content="⚡  Power Options" Style="{StaticResource NavButtonStyle}" Tag="pagePower"/>
                            <Button x:Name="navGameMode" Content="⚡  Game Mode" Style="{StaticResource NavButtonStyle}" Tag="pageGameMode"/>
                            <Button x:Name="navMemory" Content="⚡  Memory" Style="{StaticResource NavButtonStyle}" Tag="pageMemory"/>
                            <Button x:Name="navServices" Content="⚡  Services" Style="{StaticResource NavButtonStyle}" Tag="pageServices"/>
                            <Button x:Name="navTweaks" Content="⚡  System Tweaks" Style="{StaticResource NavButtonStyle}" Tag="pageTweaks"/>
                            <Button x:Name="navGPU" Content="⚡  GPU" Style="{StaticResource NavButtonStyle}" Tag="pageGPU"/>
                            <Button x:Name="navIntegrations" Content="⚡  Integrations" Style="{StaticResource NavButtonStyle}" Tag="pageIntegrations"/>
                            <Button x:Name="navPrivacy" Content="⚡  Privacy" Style="{StaticResource NavButtonStyle}" Tag="pagePrivacy"/>
                        </StackPanel>

                        <!-- WINDOWS section (collapsible) -->
                        <Button x:Name="hdrWindows" Content="[+] WINDOWS" Style="{StaticResource NavHeaderStyle}"/>
                        <StackPanel x:Name="secWindows" Visibility="Collapsed">
                            <Button x:Name="navW11" Content="⊞  Windows 11" Style="{StaticResource NavButtonStyle}" Tag="pageW11"/>
                            <Button x:Name="navBrowser" Content="⊞  Browser" Style="{StaticResource NavButtonStyle}" Tag="pageBrowser"/>
                            <Button x:Name="navContext" Content="⊞  Context Menu" Style="{StaticResource NavButtonStyle}" Tag="pageContext"/>
                        </StackPanel>

                        <!-- TOOLS section (collapsible) -->
                        <Button x:Name="hdrShortcuts" Content="[+] SHORTCUTS" Style="{StaticResource NavHeaderStyle}"/>
            <StackPanel x:Name="secShortcuts" Visibility="Collapsed">
                <Button x:Name="navWinShortcuts" Content="⊞  Windows Config" Style="{StaticResource NavButtonStyle}" Tag="pageWinShortcuts"/>
            </StackPanel>

            <Button x:Name="hdrTools" Content="[+] TOOLS" Style="{StaticResource NavHeaderStyle}"/>
                        <StackPanel x:Name="secTools" Visibility="Collapsed">
                            <Button x:Name="navUtilities" Content="⚡  Utilities" Style="{StaticResource NavButtonStyle}" Tag="pageUtilities"/>
                            <Button x:Name="navPlaybooks" Content="⬇  Playbooks Download" Style="{StaticResource NavButtonStyle}" Tag="pagePlaybooks"/>
                        </StackPanel>

                    </StackPanel>
                </ScrollViewer>
            </Border>

            <!-- ==================== RIGHT CONTENT AREA ==================== -->
            <Grid Grid.Column="1">
                <Grid.RowDefinitions>
                    <RowDefinition Height="*"/>
                    <RowDefinition Height="Auto"/>
                </Grid.RowDefinitions>

                <!-- Page content scroll area -->
                <ScrollViewer Grid.Row="0" VerticalScrollBarVisibility="Auto">
                    <ScrollViewer.Resources>
                        <Style TargetType="ScrollBar">
                            <Setter Property="Width" Value="8"/>
                            <Setter Property="Background" Value="#161B22"/>
                            <Setter Property="Template">
                                <Setter.Value>
                                    <ControlTemplate TargetType="ScrollBar">
                                        <Border Background="{TemplateBinding Background}" CornerRadius="4">
                                            <Track x:Name="PART_Track" IsDirectionReversed="True">
                                                <Track.Thumb>
                                                    <Thumb Background="#30363D" BorderThickness="0" Width="6">
                                                        <Thumb.Template>
                                                            <ControlTemplate TargetType="Thumb">
                                                                <Border Background="{TemplateBinding Background}" CornerRadius="4"/>
                                                            </ControlTemplate>
                                                        </Thumb.Template>
                                                    </Thumb>
                                                </Track.Thumb>
                                            </Track>
                                        </Border>
                                    </ControlTemplate>
                                </Setter.Value>
                            </Setter>
                        </Style>
                    </ScrollViewer.Resources>

                    <StackPanel x:Name="pnlContent" Margin="24,12,24,0">
                        <!-- Pages are injected here at runtime by PowerShell -->
                    </StackPanel>
                </ScrollViewer>

                <!-- ==================== BOTTOM BAR ==================== -->
                <Border Grid.Row="1" Background="#161B22"
                        BorderBrush="#30363D" BorderThickness="0,1,0,0"
                        Padding="12,8">
                    <Grid>
                        <Grid.RowDefinitions>
                            <RowDefinition Height="Auto"/>
                            <RowDefinition Height="Auto"/>
                        </Grid.RowDefinitions>

                        <ProgressBar Grid.Row="0" x:Name="progressBar"
                                     Style="{StaticResource ProgressBarStyle}"
                                     Minimum="0" Maximum="100" Value="0"
                                     HorizontalAlignment="Stretch"
                                     Margin="0,0,0,6"/>

                        <RichTextBox Grid.Row="1" x:Name="txtLog" Background="#0D1117" Foreground="#8B949E"
                                     BorderBrush="#30363D" BorderThickness="1"
                                     FontFamily="Consolas" FontSize="11"
                                     IsReadOnly="True" VerticalScrollBarVisibility="Auto"
                                     Height="110" Margin="0,6,0,0">
                            <RichTextBox.Resources>
                                <Style TargetType="Paragraph">
                                    <Setter Property="Margin" Value="0"/>
                                    <Setter Property="LineHeight" Value="16"/>
                                </Style>
                            </RichTextBox.Resources>
                        </RichTextBox>
                    </Grid>
                </Border>
            </Grid>
        </Grid>
    </Grid>

</Window>
"@
#endregion

# Initialize script-scope variables for ALL Programs page
$Script:AllAppsData = @{}
$Script:AllSelectedSet = New-Object 'System.Collections.Generic.List[int]'
$Script:AllInstallBtn = $null
$Script:AllWrapPanels = $null

function Invoke-AllChecked {
    param($cb, $e)
    if ($null -eq $cb -or $null -eq $cb.Tag) { return }
    $idx = [int]$cb.Tag
    $bd = $cb.Parent
    if ($bd -is [System.Windows.Controls.Border]) {
        $bd.Background = "#0D419D"
        $bd.BorderBrush = "#1F6FEB"
    }
    if ($null -ne $Script:AllSelectedSet) {
        if (-not ($Script:AllSelectedSet.Contains($idx))) {
            $Script:AllSelectedSet.Add($idx) | Out-Null
        }
    }
    $cnt = $Script:AllSelectedSet.Count
    if ($null -ne $Script:AllInstallBtn) {
        $Script:AllInstallBtn.Content = "Install Selected [$cnt]"
        $Script:AllInstallBtn.Background = if ($cnt -gt 0) { "#2EA043" } else { "#238636" }
    }
}

function Invoke-AllUnchecked {
    param($cb, $e)
    if ($null -eq $cb -or $null -eq $cb.Tag) { return }
    $idx = [int]$cb.Tag
    $bd = $cb.Parent
    if ($bd -is [System.Windows.Controls.Border]) {
        $bd.Background = "#161B22"
        $bd.BorderBrush = "#21262D"
    }
    if ($null -ne $Script:AllSelectedSet) { $Script:AllSelectedSet.Remove($idx) }
    $cnt = $Script:AllSelectedSet.Count
    if ($null -ne $Script:AllInstallBtn) {
        $Script:AllInstallBtn.Content = "Install Selected [$cnt]"
        $Script:AllInstallBtn.Background = if ($cnt -gt 0) { "#2EA043" } else { "#238636" }
    }
}

function Invoke-AllFilter {
    param($tb)
    if ($null -eq $tb) { return }
    try { $f = $tb.Text.ToLowerInvariant() } catch { return }
    if ($null -eq $Script:AllWrapPanels) { return }
    foreach ($wpanel in $Script:AllWrapPanels) {
        if ($null -eq $wpanel) { continue }
        foreach ($child in $wpanel.Children) {
            if ($child -is [System.Windows.Controls.Border] -and $child.Child -is [System.Windows.Controls.CheckBox]) {
                $txt = $child.Child.Content.ToString().ToLowerInvariant()
                $child.Visibility = if ($f -eq "" -or $txt.Contains($f)) { "Visible" } else { "Collapsed" }
            }
        }
    }
}

function Invoke-AllInstallSelected {
    if ($null -eq $Script:AllSelectedSet -or $Script:AllSelectedSet.Count -eq 0) { return }
    $count = $Script:AllSelectedSet.Count
    $ids = $Script:AllSelectedSet.ToArray() | Sort-Object
    Write-GuiLog "Installing $count selected program(s)..." "STEP"
    foreach ($idx in $ids) {
        $d2 = $Script:AllAppsData[$idx]
        if ($d2) { Invoke-InstallWingetApp $d2.Winget $d2.Name -FallbackUrl $d2.Url }
    }
    Write-GuiLog "Done." "OK"
}

