function Write-GuiLog {
    param([string]$Message, [string]$Type="INFO")
    $prefix = switch ($Type) { "OK" { "[OK]  " } "ERR" { "[ERR] " } "WARN" { "[WRN] " } "STEP" { "[>]   " } default { "[i]   " } }
    $color = switch ($Type) { "OK" { "#3FB950" } "ERR" { "#F85149" } "WARN" { "#D29922" } "STEP" { "#A371F7" } default { "#8B949E" } }
    
    $para = New-Object System.Windows.Documents.Paragraph
    $para.Margin = "0"
    $para.LineHeight = 16
    $run = New-Object System.Windows.Documents.Run("$prefix$Message")
    $colorObj = [System.Windows.Media.ColorConverter]::ConvertFromString($color)
    $run.Foreground = New-Object System.Windows.Media.SolidColorBrush($colorObj)
    $para.Inlines.Add($run)
    $txtLog.Document.Blocks.Add($para)
    $txtLog.ScrollToEnd()
}

function Set-GuiProgress { param([double]$Value, [string]$Status) 
    $progressBar.Value = $Value
    if ($Status) { Write-GuiLog $Status "STEP" }
    $Window.Dispatcher.Invoke([action]{}, [System.Windows.Threading.DispatcherPriority]::Background)
}

function Clear-GuiLog {
    $doc = New-Object System.Windows.Documents.FlowDocument
    $txtLog.Document = $doc
}

function Update-GuiNavActive { param([string]$activeTag)
    foreach ($n in $navNames) {
        $btn = $navButtons[$n]
        if ($btn) {
            $activeStyle = $Window.FindResource("NavButtonActiveStyle"); $normalStyle = $Window.FindResource("NavButtonStyle")
            if ($activeStyle -and $normalStyle) { $btn.Style = if ($btn.Tag -eq $activeTag) { $activeStyle } else { $normalStyle } }
        }
    }
}

function Clear-GuiContent { $pnlContent.Children.Clear() }

function Add-GuiCard {
    param([string]$Title, [string]$Description, [scriptblock]$Content= $null)
    $card = New-Object System.Windows.Controls.Border
    $cardStyle = $Window.FindResource("CardStyle"); if ($cardStyle) { $card.Style = $cardStyle }
    $stack = New-Object System.Windows.Controls.StackPanel
    $titleBlock = New-Object System.Windows.Controls.TextBlock
    $titleStyle = $Window.FindResource("CardTitleStyle"); if ($titleStyle) { $titleBlock.Style = $titleStyle }
    $titleBlock.Text = $Title
    $stack.AddChild($titleBlock)
    if ($Description) {
        $descBlock = New-Object System.Windows.Controls.TextBlock
        $descStyle = $Window.FindResource("CardDescStyle"); if ($descStyle) { $descBlock.Style = $descStyle }
        $descBlock.Text = $Description
        $stack.AddChild($descBlock)
    }
    if ($Content) {
        $btnPanel = New-Object System.Windows.Controls.StackPanel
        $btnPanel.Orientation = "Horizontal"
        & $Content $btnPanel
        $stack.AddChild($btnPanel)
    }
    $card.Child = $stack
    $pnlContent.AddChild($card)
}

function Add-GuiPageTitle { param([string]$Title)
    $t = New-Object System.Windows.Controls.TextBlock
    $t.Style = $Window.FindResource("PageTitleStyle")
    $t.Text = $Title
    $pnlContent.AddChild($t)
}

function Add-GuiBtn {
    param($Panel, [string]$Text, [string]$Style, $Handler)
    $btn = New-Object System.Windows.Controls.Button
    $styleObj = $Window.FindResource($Style); if ($styleObj) { $btn.Style = $styleObj }
    $btn.MinWidth = 120
    $btn.Margin = "0,2,6,2"
    $btn.Content = $Text
    $btn.Add_Click({
        Clear-GuiLog
        Set-GuiProgress 0
        $btn.IsEnabled = $false
        $Window.Cursor = [System.Windows.Input.Cursors]::Wait
        # Force a render pass now so the disabled state / wait cursor is visible
        # to the user before the (synchronous) handler potentially blocks the UI thread.
        $Window.Dispatcher.Invoke([action]{}, [System.Windows.Threading.DispatcherPriority]::Render)
        try {
            & $Handler
        } catch {
            Write-GuiLog "Unexpected error: $_" "ERR"
        } finally {
            $btn.IsEnabled = $true
            $Window.Cursor = [System.Windows.Input.Cursors]::Arrow
        }
    }.GetNewClosure())
    $Panel.AddChild($btn)
}

# Reusable pattern for the dozens of "install via winget, fallback to website" buttons.
# Collapses: Add-GuiBtn $p "Label" "ActionButtonStyle" { Invoke-InstallWingetApp "Id" "Name" -Source "x" -FallbackUrl "url" }
function Add-GuiInstallBtn {
    param($Panel, [string]$Label, [string]$Id, [string]$Name = $Label, [string]$Source = "winget", [string]$FallbackUrl = "")
    Add-GuiBtn $Panel $Label "ActionButtonStyle" { Invoke-InstallWingetApp $Id $Name -Source $Source -FallbackUrl $FallbackUrl }.GetNewClosure()
}

# Reusable pattern for the dozens of "one card with an Apply + Revert tweak pair" pages.
# Collapses: Add-GuiCard "Title" "Desc" { param($p) Add-GuiBtn $p "Apply X" "ActionButtonStyle" { Invoke-XApply }; Add-GuiBtn $p "Revert X" "RevertButtonStyle" { Invoke-XRevert } }
function Add-GuiApplyRevertCard {
    param([string]$Title, [string]$Desc, [string]$ApplyLabel, [scriptblock]$ApplyAction, [string]$RevertLabel, [scriptblock]$RevertAction)
    Add-GuiCard $Title $Desc {
        param($p)
        Add-GuiBtn $p $ApplyLabel "ActionButtonStyle" $ApplyAction
        if ($RevertLabel -and $RevertAction) { Add-GuiBtn $p $RevertLabel "RevertButtonStyle" $RevertAction }
    }.GetNewClosure()
}

#endregion

#region HELPER: REGISTRY APPLY
function Invoke-RegistryApply {
    param([array]$Settings, [string]$Label)
    $total = $Settings.Count
    $applied = 0; $failed = 0
    for ($i = 0; $i -lt $total; $i++) {
        $s = $Settings[$i]
        Set-GuiProgress ([math]::Round(($i+1)/$total*100)) "$Label : $($i+1)/$total"
        try {
            if (-not (Test-Path $s.Path)) { New-Item -Path $s.Path -Force -ErrorAction SilentlyContinue | Out-Null }
            New-ItemProperty -Path $s.Path -Name $s.Name -PropertyType $s.Type -Value $s.Value -Force -ErrorAction SilentlyContinue | Out-Null
            $applied++
        } catch { $failed++ }
    }
    Set-GuiProgress 0
    Write-GuiLog "$Label : $applied applied, $failed failed" "OK"
    return @{Applied=$applied; Failed=$failed}
}
#endregion

