        "Edge" = "$env:LOCALAPPDATA\Microsoft\Edge\User Data\Default\Cache"
        "Brave" = "$env:LOCALAPPDATA\BraveSoftware\Brave-Browser\User Data\Default\Cache"
        "Opera GX" = "$env:APPDATA\Opera Software\Opera GX Stable\Cache"
