function Show-PageHome {
    Clear-GuiContent
    
    # System Specs Card
    $info = Get-SystemInfo
    $specCard = New-Object System.Windows.Controls.Border
    $specCard.Style = $Window.FindResource("CardStyle")
    $specStack = New-Object System.Windows.Controls.StackPanel
    
    $specTitle = New-Object System.Windows.Controls.TextBlock
    $specTitle.Text = "SYSTEM SPECIFICATIONS"
    $specTitle.Foreground = "#1F6FEB"
    $specTitle.FontSize = 14
    $specTitle.FontWeight = "Bold"
    $specTitle.Margin = "0,0,0,12"
    $specStack.AddChild($specTitle)
    
    $specGrid = New-Object System.Windows.Controls.Grid
    $specGrid.ColumnDefinitions.Add((New-Object System.Windows.Controls.ColumnDefinition))
    $specGrid.ColumnDefinitions.Add((New-Object System.Windows.Controls.ColumnDefinition))
    $specGrid.RowDefinitions.Add((New-Object System.Windows.Controls.RowDefinition))
    $specGrid.RowDefinitions.Add((New-Object System.Windows.Controls.RowDefinition))
    
    $specs = @(
        @{Label="CPU"; Value=$info.CPUName},
        @{Label="RAM"; Value="$($info.RAMTotalGB) GB Total"},
        @{Label="OS"; Value="$($info.OSCaption)"},
        @{Label="GPU"; Value="$($info.GPUVendor) - $($info.GPUName) ($($info.GPUVRAM) GB VRAM)"}
    )
    
    for ($i = 0; $i -lt $specs.Count; $i++) {
        $col = $i % 2
        $row = [math]::Floor($i / 2)
        
        $stack = New-Object System.Windows.Controls.StackPanel
        $stack.Margin = if ($col -eq 0) { "0,0,20,8" } else { "20,0,0,8" }
        
        $label = New-Object System.Windows.Controls.TextBlock
        $label.Text = $specs[$i].Label
        $label.Foreground = "#8B949E"
        $label.FontSize = 11
        $stack.AddChild($label)
        
        $value = New-Object System.Windows.Controls.TextBlock
        $value.Text = $specs[$i].Value
        $value.Foreground = "#E6EDF3"
        $value.FontSize = 13
        $value.FontWeight = "SemiBold"
        $value.TextWrapping = "Wrap"
        $stack.AddChild($value)
        
        [System.Windows.Controls.Grid]::SetColumn($stack, $col)
        [System.Windows.Controls.Grid]::SetRow($stack, $row)
        $specGrid.AddChild($stack)
    }
    $specStack.AddChild($specGrid)
    $specCard.Child = $specStack
    $pnlContent.AddChild($specCard)
    
    # Restore Point Button
    Add-GuiCard "Safety First" "Create a Windows System Restore Point before making any system changes. Highly recommended." {
        param($p) Add-GuiBtn $p "Create Restore Point" "ActionButtonStyle" { Invoke-RestorePoint }
    }
    
    # Two-column layout: Cache Cleaner | Network Optimizer
    $twoColGrid = New-Object System.Windows.Controls.Grid
    $col1 = New-Object System.Windows.Controls.ColumnDefinition
    $col1.Width = "1*"
    $twoColGrid.ColumnDefinitions.Add($col1)
    $col2 = New-Object System.Windows.Controls.ColumnDefinition
    $col2.Width = "1*"
    $twoColGrid.ColumnDefinitions.Add($col2)
    $twoColGrid.HorizontalAlignment = "Stretch"
    
    # Left Column - Cache Cleaner
    $leftStack = New-Object System.Windows.Controls.StackPanel
    $leftStack.Margin = "0,0,8,0"
    
    $cacheBorder = New-Object System.Windows.Controls.Border
    $cacheBorder.Style = $Window.FindResource("CardStyle")
    $cacheInner = New-Object System.Windows.Controls.StackPanel
    
    $cacheTitle = New-Object System.Windows.Controls.TextBlock
    $cacheTitle.Style = $Window.FindResource("CardTitleStyle")
    $cacheTitle.Text = "Cache Cleaner"
    $cacheInner.AddChild($cacheTitle)
    
    $cacheWrap = New-Object System.Windows.Controls.WrapPanel
    $cacheWrap.Margin = "0,4,0,0"
    Add-GuiBtn $cacheWrap "Temp Files" "ActionButtonStyle" { Invoke-CleanTempFiles }
    Add-GuiBtn $cacheWrap "Browser Cache" "ActionButtonStyle" { Invoke-CleanBrowserCache }
    Add-GuiBtn $cacheWrap "Update Cache" "ActionButtonStyle" { Invoke-CleanUpdateCache }
    Add-GuiBtn $cacheWrap "Prefetch" "ActionButtonStyle" { Invoke-CleanPrefetch }
    Add-GuiBtn $cacheWrap "Store Cache" "ActionButtonStyle" { Invoke-CleanStoreCache }
    Add-GuiBtn $cacheWrap "Logs" "ActionButtonStyle" { Invoke-CleanLogFiles }
    Add-GuiBtn $cacheWrap "Minidumps" "ActionButtonStyle" { Invoke-CleanMemoryDumps }
    Add-GuiBtn $cacheWrap "Delivery Opt" "ActionButtonStyle" { Invoke-CleanDeliveryOpt }
    Add-GuiBtn $cacheWrap "DX Shaders" "ActionButtonStyle" { Invoke-CleanShaderCache }
    Add-GuiBtn $cacheWrap "Recycle Bin" "ActionButtonStyle" { Invoke-CleanRecycleBin }
    Add-GuiBtn $cacheWrap "Thumbnails" "ActionButtonStyle" { Invoke-CleanThumbnails }
    Add-GuiBtn $cacheWrap "Error Reports" "ActionButtonStyle" { Invoke-CleanWER }
    Add-GuiBtn $cacheWrap "Font Cache" "ActionButtonStyle" { Invoke-CleanFontCache }
    Add-GuiBtn $cacheWrap "Full Cleanup" "DangerButtonStyle" { Invoke-CleanAll }
    $cacheInner.AddChild($cacheWrap)
    
    $cacheBorder.Child = $cacheInner
    $leftStack.AddChild($cacheBorder)
    [System.Windows.Controls.Grid]::SetColumn($leftStack, 0)
    $twoColGrid.AddChild($leftStack)
    
    # Right Column - Network Optimizer  
    $rightStack = New-Object System.Windows.Controls.StackPanel
    $rightStack.Margin = "8,0,0,0"
    
    $netBorder = New-Object System.Windows.Controls.Border
    $netBorder.Style = $Window.FindResource("CardStyle")
    $netInner = New-Object System.Windows.Controls.StackPanel
    
    $netTitle = New-Object System.Windows.Controls.TextBlock
    $netTitle.Style = $Window.FindResource("CardTitleStyle")
    $netTitle.Text = "Network Optimizer"
    $netInner.AddChild($netTitle)
    
    $netWrap = New-Object System.Windows.Controls.WrapPanel
    $netWrap.Margin = "0,4,0,0"
    Add-GuiBtn $netWrap "Optimize Ethernet" "ActionButtonStyle" { Invoke-NetworkOptimize "Ethernet" }
    Add-GuiBtn $netWrap "Optimize Wi-Fi" "ActionButtonStyle" { Invoke-NetworkOptimize "WiFi" }
    Add-GuiBtn $netWrap "Revert Ethernet" "RevertButtonStyle" { Invoke-NetworkRestoreDefaults "Ethernet" }
    Add-GuiBtn $netWrap "Revert Wi-Fi" "RevertButtonStyle" { Invoke-NetworkRestoreDefaults "WiFi" }
    $netInner.AddChild($netWrap)

    $netBorder.Child = $netInner
    $rightStack.AddChild($netBorder)

    $toolsBorder = New-Object System.Windows.Controls.Border
    $toolsBorder.Style = $Window.FindResource("CardStyle")
    $toolsInner = New-Object System.Windows.Controls.StackPanel
    $toolsTitle = New-Object System.Windows.Controls.TextBlock
    $toolsTitle.Style = $Window.FindResource("CardTitleStyle")
    $toolsTitle.Text = "Tools"
    $toolsInner.AddChild($toolsTitle)
    $toolsWrap = New-Object System.Windows.Controls.WrapPanel
    $toolsWrap.Margin = "0,4,0,0"
    Add-GuiBtn $toolsWrap "DNS Jumper" "ToolButtonStyle" { Invoke-DNSTool }
    Add-GuiBtn $toolsWrap "Filter Keys" "ToolButtonStyle" { Invoke-FilterKeysTool }
    Add-GuiBtn $toolsWrap "Device Cleanup" "ToolButtonStyle" { Invoke-CleanDeviceCleanup }
    $toolsInner.AddChild($toolsWrap)
    $toolsBorder.Child = $toolsInner
    $rightStack.AddChild($toolsBorder)
    [System.Windows.Controls.Grid]::SetColumn($rightStack, 1)
    $twoColGrid.AddChild($rightStack)
    
    $pnlContent.AddChild($twoColGrid)
}

#region INSTALLERS
function Invoke-RunAllPrograms {
    $ap = Join-Path $Script:AppDir "Requirements\0_AllPrograms.exe"
    if (Test-Path $ap) { Start-Process $ap; Write-GuiLog "AllPrograms installer launched" "OK" }
    else { Write-GuiLog "0_AllPrograms.exe not found in Requirements folder" "ERR" }
}
function Invoke-InstallWingetApp {
    param([string]$Id, [string]$Name, [string]$Source="winget", [string]$FallbackUrl="")
    if (-not $Id) {
        if ($FallbackUrl) { Write-GuiLog "Opening $Name website..." "STEP"; Start-Process $FallbackUrl; Write-GuiLog "$Name download page opened" "OK" }
        else { Write-GuiLog "$Name : no download URL available" "ERR" }
        return
    }
    Write-GuiLog "Installing $Name via winget..." "STEP"
    try {
        $wingetArgs = @("install", "--id=$Id", "--silent", "--accept-source-agreements", "--accept-package-agreements")
        if ($Source -eq "msstore") { $wingetArgs += "--source", "msstore" }
        $p = Start-Process winget -ArgumentList $wingetArgs -Wait -NoNewWindow -PassThru
        if ($p.ExitCode -eq 0) { Write-GuiLog "$Name installed" "OK"; return }
        elseif ($p.ExitCode -eq -1978335189 -or $p.ExitCode -eq -1978335215) { Write-GuiLog "$Name already installed" "OK"; return }
        Write-GuiLog "Winget failed (code $($p.ExitCode)), trying fallback..." "WARN"
    } catch { Write-GuiLog "Winget error, trying fallback..." "WARN" }
    if ($FallbackUrl) {
        Write-GuiLog "Opening $Name website..." "STEP"
        Start-Process $FallbackUrl
        Write-GuiLog "$Name download page opened" "OK"
    } else { Write-GuiLog "$Name : no fallback URL available" "ERR" }
}
function Invoke-InstallRemoteScript {
    param([string]$Url, [string]$Name, [string]$FallbackUrl="")
    Write-GuiLog "Installing $Name via remote script..." "STEP"
    try {
        Invoke-Expression (Invoke-RestMethod $Url)
        Write-GuiLog "$Name installed" "OK"
    } catch {
        Write-GuiLog "$Name install failed: $_" "WARN"
        if ($FallbackUrl) {
            Write-GuiLog "Opening $Name website..." "STEP"
            Start-Process $FallbackUrl
            Write-GuiLog "$Name download page opened" "OK"
        }
    }
}
