    $essStack.AddChild($essBtns)
    $essCard.Child = $essStack
    $pnlContent.AddChild($essCard)
    
    # 4x2 grid
    $grid = New-Object System.Windows.Controls.Grid
    for ($c=0; $c -lt 4; $c++) { $cd = New-Object System.Windows.Controls.ColumnDefinition; $cd.Width = "1*"; $grid.ColumnDefinitions.Add($cd) }
    for ($r=0; $r -lt 2; $r++) { $rd = New-Object System.Windows.Controls.RowDefinition; $rd.Height = "Auto"; $grid.RowDefinitions.Add($rd) }
    $grid.HorizontalAlignment = "Stretch"
    
    function Add-CatCard { param($col, $row, $title, $desc, $btns)
        $stack = New-Object System.Windows.Controls.StackPanel; $stack.Margin = "0,0,6,0"
        $border = New-Object System.Windows.Controls.Border; $border.Style = $Window.FindResource("CardStyle")
        $inner = New-Object System.Windows.Controls.StackPanel
