        $d = New-Object System.Windows.Controls.TextBlock; $d.Text = $desc; $d.Foreground = "#8B949E"; $d.FontSize = 10; $d.TextWrapping = "Wrap"; $d.Margin = "0,0,0,8"
        $inner.AddChild($d)
        $wrap = New-Object System.Windows.Controls.WrapPanel; $wrap.Margin = "0,4,0,0"
        & $btns $wrap
        $inner.AddChild($wrap)
        $border.Child = $inner; $stack.AddChild($border)
        [System.Windows.Controls.Grid]::SetColumn($stack, $col); [System.Windows.Controls.Grid]::SetRow($stack, $row); $grid.AddChild($stack)
