# Accordion sidebar toggles
function Toggle-SidebarSection {
    param($header, $section)
    $header.Add_Click({
                         if ($section.Visibility -eq 'Collapsed') {
                                 $section.Visibility = 'Visible'
                                 $header.Content = $header.Content.ToString() -replace '\[\+\]','[-]'
                             } else {
                                 $section.Visibility = 'Collapsed'
                                 $header.Content = $header.Content.ToString() -replace '\[-\]','[+]'
                             }
                         }.GetNewClosure())
}

function Expand-Section {
    param($section, $header)
    if ($section -and $section.Visibility -eq 'Collapsed') {
        $section.Visibility = 'Visible'
        if ($header) { $header.Content = $header.Content.ToString() -replace '\[\+\]','[-]' }
    }
}

